tool_calls:
awk -F= '
NR==FNR {
    # reading overrides.txt
    if ($0 ~ /=/) {
        k = $1
        # value might contain =
        v = substr($0, length(k) + 2)
        override[k] = v
        has_override[k] = 1
    }
    next
}
{
    # reading template.env
    # lines like KEY=${VALUE:-default}
    # let us parse KEY and default
    if ($0 ~ /^[A-Za-z0-9_]+=/) {
        k = $1
        rest = substr($0, length(k) + 2)
        # rest is ${VALUE:-default}
        # extract default: find :- and closing }
        sub(/^\$\{[^:]*:-/, "", rest)
        sub(/\}$/, "", rest)
        if (has_override[k]) {
            val = override[k]
        } else {
            val = rest
        }
        print k "=" val
    }
}
' /config/overrides.txt /config/template.env

